import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './css/HealthAssessment.css';

function HealthAssessment() {
  const navigate = useNavigate();
  const API_BASE_URL = 
    process.env.NODE_ENV === 'production'
      ? 'https://airaware-app-gcw7.onrender.com'
      : 'http://localhost:8000';

  // CSRF Token Retrieval
  const getCsrfToken = () => {
    const cookies = document.cookie.split(';');
    for (let cookie of cookies) {
      const [name, value] = cookie.trim().split('=');
      if (name === 'csrftoken') {
        return decodeURIComponent(value);
      }
    }
    return null;
  };

  // Initial Form State
  const [formData, setFormData] = useState({
    user_id: null,
    age_group: '',
    gender: '',
    respiratory_conditions: [],
    smoking_history: '',
    living_environment: [],
    common_symptoms: [],
    occupational_exposure: '',
    medical_history: []
  });

  // Error and Submission State
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Predefined Options
  const options = {
    ageGroups: [
      '0-12 years', '13-18 years', '19-35 years', 
      '36-50 years', '51-65 years', '65+ years'
    ],
    respiratoryConditions: [
      'Asthma', 'COPD', 'Bronchitis', 'None'
    ],
    smokingHistory: [
      'Never smoker', 'Current smoker', 'Former smoker'
    ],
    livingEnvironments: [
      'Urban', 'Suburban', 'Rural', 'Industrial Area'
    ],
    commonSymptoms: [
      'Cough', 'Shortness of Breath', 'Chest Pain', 'Wheezing', 'None'
    ]
  };

  // Lifecycle to set user_id
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user'));
    if (user && user.user_id) {
      setFormData(prev => ({
        ...prev,
        user_id: user.user_id
      }));
    } else {
      setError('User not authenticated. Please log in again.');
      navigate('/login');
    }
  }, [navigate]);

  // Comprehensive Change Handler
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData(prev => {
      if (type === 'checkbox') {
        const currentValues = prev[name] || [];
        return {
          ...prev,
          [name]: checked 
            ? [...currentValues, value]
            : currentValues.filter(item => item !== value)
        };
      }
      return { ...prev, [name]: value };
    });
  };

  // Submission Handler with Comprehensive Error Handling
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    // Basic Validation
    if (!formData.user_id) {
      setError('User ID is missing. Please log in again.');
      setLoading(false);
      return;
    }

    if (!formData.age_group || !formData.gender) {
      setError('Please complete required fields');
      setLoading(false);
      return;
    }

    try {
      // Get CSRF Token
      const csrfToken = getCsrfToken();
      console.log('CSRF Token:', csrfToken);

      const response = await fetch(`${API_BASE_URL}/api/health-assessment/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRFToken': csrfToken,
        },
        credentials: 'include',
        body: JSON.stringify(formData)
      });

      // Detailed Error Logging
      if (!response.ok) {
        const errorText = await response.text();
        console.error('Submission Error:', {
          status: response.status,
          statusText: response.statusText,
          body: errorText
        });
        
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      // Update localStorage
      const user = JSON.parse(localStorage.getItem('user'));
      localStorage.setItem('user', JSON.stringify({
        ...user,
        has_health_assessment: true
      }));

      // Navigate to dashboard
      navigate('/dashboard');

    } catch (error) {
      console.error('Health Assessment Error:', error);
      setError(error.message || 'Failed to submit health assessment');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="health-assessment-container">
      <h2>Health Assessment</h2>
      
      {error && <div className="error-message">{error}</div>}

      <form onSubmit={handleSubmit}>
        {/* Age Group */}
        <div className="form-group">
          <label>Age Group</label>
          <select 
            name="age_group"
            value={formData.age_group}
            onChange={handleChange}
            required
          >
            <option value="">Select Age Group</option>
            {options.ageGroups.map(group => (
              <option key={group} value={group}>{group}</option>
            ))}
          </select>
        </div>

        {/* Gender */}
        <div className="form-group">
          <label>Gender</label>
          <select 
            name="gender"
            value={formData.gender}
            onChange={handleChange}
            required
          >
            <option value="">Select Gender</option>
            <option value="Male">Male</option>
            <option value="Female">Female</option>
            <option value="Other">Other</option>
          </select>
        </div>

        {/* Respiratory Conditions */}
        <div className="form-group">
          <label>Respiratory Conditions</label>
          {options.respiratoryConditions.map(condition => (
            <label key={condition}>
              <input 
                type="checkbox"
                name="respiratory_conditions"
                value={condition}
                checked={formData.respiratory_conditions.includes(condition)}
                onChange={handleChange}
              />
              {condition}
            </label>
          ))}
        </div>

        {/* Smoking History */}
        <div className="form-group">
          <label>Smoking History</label>
          <select 
            name="smoking_history"
            value={formData.smoking_history}
            onChange={handleChange}
          >
            <option value="">Select Smoking History</option>
            {options.smokingHistory.map(status => (
              <option key={status} value={status}>{status}</option>
            ))}
          </select>
        </div>

        {/* Living Environment */}
        <div className="form-group">
          <label>Living Environment</label>
          {options.livingEnvironments.map(environment => (
            <label key={environment}>
              <input 
                type="checkbox"
                name="living_environment"
                value={environment}
                checked={formData.living_environment.includes(environment)}
                onChange={handleChange}
              />
              {environment}
            </label>
          ))}
        </div>

        {/* Common Symptoms */}
        <div className="form-group">
          <label>Common Symptoms</label>
          {options.commonSymptoms.map(symptom => (
            <label key={symptom}>
              <input 
                type="checkbox"
                name="common_symptoms"
                value={symptom}
                checked={formData.common_symptoms.includes(symptom)}
                onChange={handleChange}
              />
              {symptom}
            </label>
          ))}
        </div>

        {/* Occupational Exposure */}
        <div className="form-group">
          <label>Occupational Exposure</label>
          <input 
            type="text"
            name="occupational_exposure"
            value={formData.occupational_exposure}
            onChange={handleChange}
            placeholder="Describe your workplace environment"
          />
        </div>

        <button 
          type="submit" 
          disabled={loading}
        >
          {loading ? 'Submitting...' : 'Submit Assessment'}
        </button>
      </form>
    </div>
  );
}

export default HealthAssessment;
